DROP DATABASE IF EXISTS bd_tw_maintflow;
CREATE DATABASE bd_tw_maintflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bd_tw_maintflow;
CREATE TABLE roles(id_rol INT AUTO_INCREMENT PRIMARY KEY,nombre_rol VARCHAR(30) UNIQUE NOT NULL,descripcion VARCHAR(150),estado TINYINT DEFAULT 1);
CREATE TABLE usuarios(id_usuario INT AUTO_INCREMENT PRIMARY KEY,id_rol INT NOT NULL,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,nombres VARCHAR(80) NOT NULL,apellidos VARCHAR(80) NOT NULL,correo VARCHAR(120),estado TINYINT DEFAULT 1,fecha_registro DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(id_rol) REFERENCES roles(id_rol));
CREATE TABLE clientes(id_cliente INT AUTO_INCREMENT PRIMARY KEY,razon_social VARCHAR(150) NOT NULL,ruc CHAR(11) UNIQUE NOT NULL,contacto VARCHAR(120),telefono VARCHAR(20),correo VARCHAR(120),direccion VARCHAR(180),estado TINYINT DEFAULT 1,fecha_registro DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sedes(id_sede INT AUTO_INCREMENT PRIMARY KEY,id_cliente INT NOT NULL,nombre_sede VARCHAR(120) NOT NULL,direccion VARCHAR(180),distrito VARCHAR(80),provincia VARCHAR(80),departamento VARCHAR(80),estado TINYINT DEFAULT 1,FOREIGN KEY(id_cliente) REFERENCES clientes(id_cliente));
CREATE TABLE categorias_equipo(id_categoria INT AUTO_INCREMENT PRIMARY KEY,nombre_categoria VARCHAR(100) UNIQUE NOT NULL,descripcion VARCHAR(180),estado TINYINT DEFAULT 1);
CREATE TABLE equipos(id_equipo INT AUTO_INCREMENT PRIMARY KEY,id_sede INT NOT NULL,id_categoria INT NOT NULL,codigo_equipo VARCHAR(30) UNIQUE NOT NULL,nombre_equipo VARCHAR(120) NOT NULL,marca VARCHAR(80),modelo VARCHAR(80),numero_serie VARCHAR(80),fecha_adquisicion DATE,estado_operativo VARCHAR(30) DEFAULT 'Operativo',observaciones TEXT,FOREIGN KEY(id_sede) REFERENCES sedes(id_sede),FOREIGN KEY(id_categoria) REFERENCES categorias_equipo(id_categoria));
CREATE TABLE tecnicos(id_tecnico INT AUTO_INCREMENT PRIMARY KEY,id_usuario INT UNIQUE NOT NULL,especialidad VARCHAR(100),telefono VARCHAR(20),fecha_ingreso DATE,estado TINYINT DEFAULT 1,FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario));
CREATE TABLE estados_orden(id_estado INT AUTO_INCREMENT PRIMARY KEY,nombre_estado VARCHAR(40) UNIQUE NOT NULL,descripcion VARCHAR(150),orden_visual INT NOT NULL);
CREATE TABLE ordenes_servicio(id_orden INT AUTO_INCREMENT PRIMARY KEY,id_equipo INT NOT NULL,id_tecnico INT,id_estado INT NOT NULL,tipo_mantenimiento ENUM('Preventivo','Correctivo') NOT NULL,prioridad ENUM('Baja','Media','Alta','Crítica') DEFAULT 'Media',fecha_solicitud DATETIME DEFAULT CURRENT_TIMESTAMP,fecha_programada DATE,fecha_inicio DATETIME,fecha_cierre DATETIME,descripcion_falla TEXT NOT NULL,diagnostico TEXT,solucion TEXT,observaciones TEXT,costo_mano_obra DECIMAL(10,2) DEFAULT 0,costo_total DECIMAL(10,2) DEFAULT 0,FOREIGN KEY(id_equipo) REFERENCES equipos(id_equipo),FOREIGN KEY(id_tecnico) REFERENCES tecnicos(id_tecnico),FOREIGN KEY(id_estado) REFERENCES estados_orden(id_estado));
CREATE TABLE repuestos(id_repuesto INT AUTO_INCREMENT PRIMARY KEY,codigo_repuesto VARCHAR(30) UNIQUE NOT NULL,nombre_repuesto VARCHAR(120) NOT NULL,descripcion VARCHAR(180),unidad_medida VARCHAR(30),stock_actual DECIMAL(10,2) DEFAULT 0,stock_minimo DECIMAL(10,2) DEFAULT 0,precio_unitario DECIMAL(10,2) DEFAULT 0,estado TINYINT DEFAULT 1);
CREATE TABLE detalle_orden(id_detalle INT AUTO_INCREMENT PRIMARY KEY,id_orden INT NOT NULL,id_repuesto INT NULL,descripcion_actividad VARCHAR(255) NOT NULL,cantidad DECIMAL(10,2) DEFAULT 0,precio_unitario DECIMAL(10,2) DEFAULT 0,subtotal DECIMAL(10,2) GENERATED ALWAYS AS(cantidad*precio_unitario) STORED,FOREIGN KEY(id_orden) REFERENCES ordenes_servicio(id_orden),FOREIGN KEY(id_repuesto) REFERENCES repuestos(id_repuesto));
CREATE TABLE movimientos_repuesto(id_movimiento INT AUTO_INCREMENT PRIMARY KEY,id_repuesto INT NOT NULL,id_usuario INT NOT NULL,tipo_movimiento ENUM('Entrada','Salida','Ajuste') NOT NULL,cantidad DECIMAL(10,2) NOT NULL,motivo VARCHAR(180),fecha_movimiento DATETIME DEFAULT CURRENT_TIMESTAMP,referencia VARCHAR(80),FOREIGN KEY(id_repuesto) REFERENCES repuestos(id_repuesto),FOREIGN KEY(id_usuario) REFERENCES usuarios(id_usuario));
