DELIMITER $$
CREATE TRIGGER tr_detalle_stock AFTER INSERT ON detalle_orden FOR EACH ROW BEGIN IF NEW.id_repuesto IS NOT NULL AND NEW.cantidad>0 THEN UPDATE repuestos SET stock_actual=stock_actual-NEW.cantidad WHERE id_repuesto=NEW.id_repuesto; UPDATE ordenes_servicio SET costo_total=costo_mano_obra+(SELECT COALESCE(SUM(subtotal),0) FROM detalle_orden WHERE id_orden=NEW.id_orden) WHERE id_orden=NEW.id_orden; END IF; END$$
CREATE PROCEDURE sp_cerrar_orden(IN p_id INT) BEGIN UPDATE ordenes_servicio SET id_estado=5,fecha_cierre=NOW() WHERE id_orden=p_id; END$$
CREATE FUNCTION fn_total_orden(p_id INT) RETURNS DECIMAL(10,2) DETERMINISTIC BEGIN DECLARE t DECIMAL(10,2); SELECT costo_mano_obra+COALESCE((SELECT SUM(subtotal) FROM detalle_orden WHERE id_orden=p_id),0) INTO t FROM ordenes_servicio WHERE id_orden=p_id; RETURN t; END$$
DELIMITER ;

